-- gerado por gen_ensaio.py; requer temp table tempos e current_setting('rl.fase')
reset role;
select set_config('request.jwt.claims', json_build_object('sub','0a321807-c739-4b26-89e7-6e6fdef00297','role','authenticated')::text, true), set_config('request.jwt.claim.sub','0a321807-c739-4b26-89e7-6e6fdef00297', true), set_config('mt.ctx', '', true), set_config('mt.ctx_m', '', true);
set local role authenticated;
do $t$ declare t0 timestamptz; ms numeric; melhor numeric; i int; begin
  melhor := null; for i in 1..3 loop t0 := clock_timestamp(); begin execute 'select public.dashboard_stats()'; exception when others then null; end; ms := extract(epoch from clock_timestamp() - t0) * 1000; melhor := least(coalesce(melhor, ms), ms); end loop; insert into tempos values (current_setting('rl.fase'), 'super_admin', 'dashboard_stats', round(melhor, 1));
  melhor := null; for i in 1..3 loop t0 := clock_timestamp(); begin execute 'select count(*) from public.vendas_comerciais_canonicas()'; exception when others then null; end; ms := extract(epoch from clock_timestamp() - t0) * 1000; melhor := least(coalesce(melhor, ms), ms); end loop; insert into tempos values (current_setting('rl.fase'), 'super_admin', 'vendas_comerciais_canonicas', round(melhor, 1));
  melhor := null; for i in 1..3 loop t0 := clock_timestamp(); begin execute 'select count(*) from public.financeiro_distribuicao_vendas()'; exception when others then null; end; ms := extract(epoch from clock_timestamp() - t0) * 1000; melhor := least(coalesce(melhor, ms), ms); end loop; insert into tempos values (current_setting('rl.fase'), 'super_admin', 'financeiro_distribuicao_vendas', round(melhor, 1));
  melhor := null; for i in 1..3 loop t0 := clock_timestamp(); begin execute 'select count(*) from public.comparativo_comissao_6pct_inconsistencias()'; exception when others then null; end; ms := extract(epoch from clock_timestamp() - t0) * 1000; melhor := least(coalesce(melhor, ms), ms); end loop; insert into tempos values (current_setting('rl.fase'), 'super_admin', 'comparativo_6pct_inconsistencias', round(melhor, 1));
  melhor := null; for i in 1..3 loop t0 := clock_timestamp(); begin execute 'select public.list_vendas_comerciais_paginadas(0, 10)'; exception when others then null; end; ms := extract(epoch from clock_timestamp() - t0) * 1000; melhor := least(coalesce(melhor, ms), ms); end loop; insert into tempos values (current_setting('rl.fase'), 'super_admin', 'list_vendas_comerciais_paginadas', round(melhor, 1));
end $t$;
